const n=chrome.runtime.getManifest().version;console.info(`[ghost-image-editor] background loaded v${n}`);chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"editImage",title:chrome.i18n.getMessage("contextEdit"),contexts:["image"]})});chrome.contextMenus.onClicked.addListener((t,e)=>{t.menuItemId!=="editImage"||!(e!=null&&e.id)||!t.srcUrl||chrome.tabs.sendMessage(e.id,{type:"OPEN_EDITOR_FROM_CONTEXT",imageSrc:t.srcUrl})});
